import sys

def read_line():
	return sys.stdin.readline().split()

def read_int():
	return int(sys.stdin.readline())

def read_int_line():
	return [int(v) for v in sys.stdin.readline().split()]

def gcd(x, y):
	while x != 0 and y != 0:
		z = y
		y = x % y
		x = z
	return x + y

def compute_other_gcd(A, gcd1):
	ret = 0
	for x in A:
		if x % gcd1 != 0:
			ret = gcd(ret, x)
	if ret == 0:
		return A[-1]
	return ret
T = read_int()
for _test in range(T):
	N = read_int()
	A = read_int_line()
	A.sort()
	d = 1
	answer = 0
	while d * d <= A[0]:
		if A[0] % d == 0:
			answer = max(answer, d + compute_other_gcd(A, d))
			answer = max(answer, A[0] // d + compute_other_gcd(A, A[0] // d))
		d += 1
	print(answer)
